package dev.alializadeh.orbit.ui.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialExpressiveTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import com.materialkolor.PaletteStyle
import com.materialkolor.dynamiccolor.ColorSpec
import com.materialkolor.material3.rememberDynamicColorScheme

/**
 * Orbit's Material 3 Expressive theme: a TonalSpot scheme generated by MaterialKolor (SPEC_2025)
 * from [seedColor], with apricot as the tertiary key colour, light or dark following the system.
 *
 * Slice 1 adds the colour-source setting (Match wallpaper, Your colour) on top of this.
 */
@Composable
fun OrbitTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    seedColor: Color = OrbitViolet,
    content: @Composable () -> Unit,
) {
    val colorScheme = rememberDynamicColorScheme(
        seedColor = seedColor,
        isDark = darkTheme,
        tertiary = Apricot,
        style = PaletteStyle.TonalSpot,
        specVersion = ColorSpec.SpecVersion.SPEC_2025,
    )
    val context = LocalContext.current
    val typography = remember(context) { orbitTypography(OrbitFonts.get(context)) }
    MaterialExpressiveTheme(
        colorScheme = colorScheme,
        typography = typography,
        content = content,
    )
}
